 <body>
   <main class="card">
     <p class="eyebrow">Preferences</p>
     <h1>Choose your notification style</h1>
     <p class="intro">Tell us how you prefer to receive updates so we can keep your experience tailored and timely.</p>

     <form id="notification-form">
       <div class="form-field">
         <fieldset>
           <legend>How do you prefer to receive notifications?</legend>

           <label class="option" for="notification-email">
             <input id="notification-email" type="radio" name="notificationPreference" value="Email" required>
             <span class="option-text">Email</span>
           </label>

           <label class="option" for="notification-sms">
             <input id="notification-sms" type="radio" name="notificationPreference" value="SMS">
             <span class="option-text">SMS</span>
           </label>

           <label class="option" for="notification-push">
             <input id="notification-push" type="radio" name="notificationPreference" value="Push Notifications">
             <span class="option-text">Push Notifications</span>
           </label>
         </fieldset>
       </div>

       <div class="actions">
         <button type="submit">Submit</button>
         <p id="status" class="status" aria-live="polite"></p>
       </div>
     </form>
   </main>

   <script>
     const form = document.getElementById("notification-form");
     const status = document.getElementById("status");

     form.addEventListener("submit", function (event) {
       event.preventDefault();

       const selected = form.querySelector('input[name="notificationPreference"]:checked');
       status.textContent = selected
         ? "Preference saved: " + selected.value
         : "Please choose one option before submitting.";
     });
   </script>
